import{_ as t,o,c as a,a2 as r}from"./chunks/framework.DzNHXt93.js";const p=JSON.parse('{"title":"takoform_worker_endpoint","description":"Worker Endpoint (edge.forms.takoform.com/v1alpha1, role attachment).","frontmatter":{"page_title":"takoform_worker_endpoint Resource - takoform","subcategory":"Edge Platform Family","description":"Worker Endpoint (edge.forms.takoform.com/v1alpha1, role attachment)."},"headers":[],"relativePath":"docs/resources/worker_endpoint.md","filePath":"docs/resources/worker_endpoint.md"}'),n={name:"docs/resources/worker_endpoint.md"};function s(i,e,d,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="takoform-worker-endpoint" tabindex="-1">takoform_worker_endpoint <a class="header-anchor" href="#takoform-worker-endpoint" aria-label="Permalink to &quot;takoform_worker_endpoint&quot;">​</a></h1><p>Makes one Module Worker reachable over HTTPS at an address the HOST assigns, with no customer-owned domain and no DNS of the author&#39;s. The desired state is the worker and nothing else: the author asks for reachability, and where that reachability lives is the host&#39;s decision, exactly as an account, a region, and a vendor subdomain are. Requests arriving at the address invoke the fetch handler of the worker&#39;s ACTIVE DEPLOYMENT, so promotion and rollback move what answers without the endpoint being re-applied and without its address changing. The scheme is https and the path root is <code>/</code>; TLS is not an option a host may decline, because an address that is only reachable in plaintext is a different promise from the one this Form makes. A worker has AT MOST ONE endpoint: two would be two addresses for one service with nothing saying which is canonical, and the second is refused. The assigned address is published as outputs — a portable author may rely on a value being returned, on its scheme being https, and on it routing to the active deployment, and on nothing about its SHAPE: which subdomain, which apex, and how long the label is are host detail no portable configuration may parse or reconstruct.</p><p>This is an <code>attachment</code> resource: it connects a parent to inward activation (routes, domains, schedules, queue consumption). Deleting the attachment never deletes the parent.</p><p>This resource speaks the Host API v1alpha3 lane and requires provider v2.1.0 or later (source candidate; not yet published). The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_worker_endpoint/resource.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>worker</code> (String, required, forces replacement) — Module Worker whose active deployment answers requests at the assigned address. Changing it replaces the endpoint. Set the name of the target <code>ModuleWorker</code> resource.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>30m</code>). There is no <code>update_timeout</code>: this Form declares no update capability. Changing only these provider-side timeouts is applied in place without any host call.</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes; this Form declares no update capability — every desired attribute forces replacement instead.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, or new outputs. Deletes fence on it via <code>If-Match</code>.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — the WHOLE <code>status.outputs</code> document, JSON-serialized. It is not narrowed by the typed output attributes below: every value that has a typed attribute is still in this document under its wire name, so a configuration that reads <code>jsondecode(...)[&quot;…&quot;]</code> keeps working unchanged. What it is now FOR is the other case — reaching an output the Form&#39;s <code>outputSchema</code> does not describe.</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes replacing this resource, because this Form declares no in-place update and a host refuses every apply to the existing one. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h2><p>This Form declares an <code>outputSchema</code>, so a conforming host returns exactly these values in <code>status.outputs</code> and the provider surfaces each one as a typed computed attribute. Read <code>takoform_worker_endpoint.example.&lt;name&gt;</code> rather than decoding <code>outputs_json</code>; the JSON document still carries every value under its wire name and stays the way to reach an output no schema describes.</p><ul><li><code>hostname</code> (String, computed) — Dotted DNS hostname the host assigned to this endpoint, in canonical form: lowercase where DNS is case-insensitive and no trailing root dot. An author&#39;s hostname admits those spellings because a host canonicalizes what it is given; an assigned name has no earlier spelling to preserve. Its VALUE is portable to read and pass on; its SHAPE is host detail, so a portable configuration never parses it, never asserts a suffix, and never reconstructs it from the resource name.</li><li><code>url</code> (String, computed) — Absolute HTTPS URL of the endpoint&#39;s path root: exactly <code>https://</code> + the assigned hostname + <code>/</code>. The scheme is fixed by the Form and the path root is <code>/</code>; there is no plaintext address and no port, so a consumer composes deeper paths onto this value rather than deriving an origin.</li></ul><p>Outputs are never arguments: a configuration that sets one is rejected at validate time. They are host-computed state, so they can change without any desired attribute changing — a plan that touches this resource shows them as known-after-apply.</p><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>WorkerEndpoint</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_endpoint.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_endpoint.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_endpoint.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com/v1alpha1&quot;,&quot;kind&quot;:&quot;WorkerEndpoint&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p>`,19)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
